(4312, 0, 0, 'itIT', 'Grunt! All''attacco!'),
(4314, 0, 0, 'itIT', 'Guardie!'),
(4317, 0, 0, 'itIT', 'Non profanerai la nostra sacra terra!'),
(4319, 0, 0, 'itIT', 'Guardie! Aiutatemi!'),
(4321, 0, 0, 'itIT', 'Guardie! Aiutatemi!'),
(4351, 0, 0, 'itIT', '%s sembra abbastanza debole da poter essere catturato!'),
