(4831, 1, 0, 'itIT', 'Una cosa da nulla!'),
(4832, 0, 0, 'itIT', 'Chi osa disturbare la mia meditazione?'),
(4832, 2, 0, 'itIT', 'Polvere alla polvere.'),
