(5236, 0, 2, 'itIT', 'Raaar!!! Io schiacciare $R!'),
(5237, 0, 1, 'itIT', 'Io schiacciare, tu morire!'),
(5238, 0, 1, 'itIT', 'Io schiacciare, tu morire!'),
(5239, 0, 1, 'itIT', 'Io schiacciare, tu morire!'),
