(10665, 0, 0, 'itIT', 'Perché ci vuole così tanto?'),
(10665, 0, 1, 'itIT', 'Quanto ci vuole per raccogliere un po'' d''erba?'),
(10665, 0, 2, 'itIT', 'Di questo passo avrei fatto prima da solo!'),
(10665, 0, 3, 'itIT', 'Se vuoi una cosa fatta bene, devi fartela da solo!'),
