(11382, 1, 0, 'itIT', 'DING!'),
(11382, 1, 1, 'itIT', 'I morti vuostr'' alimenteranno la forza mia!'),
(11382, 4, 0, 'itIT', 'Il %s s''infuria vedendo il suo raptor cadere in battaglia!'),
(11440, 0, 0, 'itIT', 'Io schiacciare te!'),
(11440, 0, 1, 'itIT', 'Io non stare bene.'),
(11440, 0, 2, 'itIT', 'Io schiacciare, tu morire!'),
