(19044, 3, 0, 'itIT', 'Non esisti più.'),
(19044, 3, 1, 'itIT', 'Non vali nulla.'),
(19044, 3, 2, 'itIT', 'Muori.'),
(19044, 5, 0, 'itIT', '%s aumenta di dimensioni!'),
(19138, 0, 0, 'itIT', 'Così sia.'),
